FUNCTION_BLOCK FB_S05
VAR_INPUT
    FlowPulse : BOOL;
    ShiftReset : BOOL;
    CycleTime : TIME;
END_VAR
VAR_OUTPUT
    TotalVolume : LREAL := LREAL#0.0;
    ShiftVolume : LREAL := LREAL#0.0;
    PulseCount : UDINT := UDINT#0;
    OverflowFlag : BOOL := FALSE;
    Status : WORD := WORD#16#0000;
END_VAR
VAR
    FlowPulseLast : BOOL := FALSE;
    ShiftResetLast : BOOL := FALSE;
    FlowRise : BOOL := FALSE;
    ResetRise : BOOL := FALSE;
END_VAR

(*
需求原文：
泵站出口装有脉冲流量计，每个脉冲代表 0.5 L。需要同时维护累计总量与当班流量。

控制要求：
1. FlowPulse 的每个上升沿使 PulseCount 加 1，TotalVolume 与 ShiftVolume 各加 0.5 L。
2. ShiftReset 的上升沿把 ShiftVolume 清 0、PulseCount 清 0，但 TotalVolume 必须保持不变。
3. TotalVolume 达到 1000000.0 L 时不再增加，置 OverflowFlag = TRUE；
   清零只能由维护流程完成（本题不提供入口，仅置位）。
4. FlowPulse 为高频脉冲，同一扫描周期内最多计一个脉冲
   （20 ms 周期内不允许丢脉冲的假设不成立时，以 Status 报 16#8501）。
5. 上电时 PulseCount = 0、TotalVolume = 0.0、ShiftVolume = 0.0、
   OverflowFlag = FALSE。
6. Status：16#0000 正常、16#8501 脉冲过快、16#8502 总量溢出。

扫描周期：20 ms。

待审：现有接口不能完整满足以下要求，未新增接口或制造判据。
A. 每次调用只得到一个 BOOL 采样，无法观测采样之间的多次上升沿。
   CycleTime 仅提供周期长度，不能提供遗漏的边沿数。
   因而无法实现 K4 的多脉冲检测，也不能可靠产生 16#8501。
   本实现只计可观测的采样上升沿，不用连续高电平或周期长度伪造过快诊断。
B. 总量封顶后，要求1仍要求当班量随脉冲增加，这与 C6
   ShiftVolume <= TotalVolume 冲突。本实现保留当班独立累计，
   不为满足 C6 擅自封顶当班量；因此 C6 无法普遍成立。
C. C10 要求上电前两个观察周期累计量为零，与这些周期中出现
   FlowPulse 上升沿必须计数的要求冲突。本实现采用声明初态，
   从首次调用开始处理上升沿，不屏蔽启动期间的脉冲。
D. 同周期复位与流量上升沿对当班结果存在冲突：
   本实现按复位优先处理当班量和当班脉冲数，
   但流量上升沿仍计入累计总量。
E. UDINT 无法无限加1。本实现达到 UDINT 上限后饱和以避免回绕；
   上限后的精确计数需求及对应状态码未定义，需审定。
   LREAL 的有限精度也不能保证无限运行后每次仍精确增加0.5。

以下实现不表示全部规约已满足，也未声明通过编译或逐周期测试。
*)

FlowRise := FlowPulse AND NOT FlowPulseLast;
ResetRise := ShiftReset AND NOT ShiftResetLast;

FlowPulseLast := FlowPulse;
ShiftResetLast := ShiftReset;

(* 总量不受班次复位影响；达到上限的本周期立即置位。 *)
IF FlowRise THEN
    IF TotalVolume < LREAL#1000000.0 THEN
        IF TotalVolume >= LREAL#999999.5 THEN
            TotalVolume := LREAL#1000000.0;
        ELSE
            TotalVolume := TotalVolume + LREAL#0.5;
        END_IF;
    END_IF;
END_IF;

IF TotalVolume >= LREAL#1000000.0 THEN
    TotalVolume := LREAL#1000000.0;
    OverflowFlag := TRUE;
END_IF;

(* 当班复位优先；复位不清除累计总量或锁存的溢出标志。 *)
IF ResetRise THEN
    ShiftVolume := LREAL#0.0;
    PulseCount := UDINT#0;
ELSIF FlowRise THEN
    ShiftVolume := ShiftVolume + LREAL#0.5;

    IF PulseCount < UDINT#4294967295 THEN
        PulseCount := PulseCount + UDINT#1;
    END_IF;
END_IF;

(* 16#0000 仅表示未产生可实现的溢出诊断，不证明没有漏脉冲。
   溢出状态随 OverflowFlag 永久保持；过快诊断受上述接口限制。 *)
IF OverflowFlag THEN
    Status := WORD#16#8502;
ELSE
    Status := WORD#16#0000;
END_IF;

END_FUNCTION_BLOCK
